mapper.select:
SELECT 
FROM cases c INNER JOIN reporters r ON r.id = c.reporter_id
WHERE c.id = #{id}

SELECT id, status, photo_s3_key
FROM cases
WHERE id = #{id}

mapper.update:
UPDATE reporters
SET name = #{reporterName}, phone = #{reporterPhone}, email = #{reporterEmail},
    relation = #{reporterRelation}
WHERE id = #{reporterId}

UPDATE cases
SET status = #{status}, closed_at = #{closedAt}, updated_at = UTC_TIMESTAMP(6)
WHERE id = #{id}

UPDATE cases
SET photo_s3_key = #{photoS3Key}, updated_at = UTC_TIMESTAMP(6)
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM analysis_jobs
WHERE case_id = #{caseId}
  AND search_condition_id = #{conditionId}
  AND status IN ('QUEUED', 'RUNNING')

SELECT c.id AS case_id, c.case_number, sc.id AS condition_id, sc.prompt, sc.exclusion_prompt, sc.search_start, sc.search_end, sc.search_area, sc.similarity_threshold, c.updated_at AS target_updated_at FROM cases c INNER JOIN search_conditions sc ON sc.case_id = c.id AND sc.deleted_at IS NULL WHERE c.status = 'SEARCHING' AND c.id IN
#{caseId}
ORDER BY c.id, sc.id
